'use client';

import { useEffect, useState } from 'react';

interface SkyPoint {
  timeUTC: string;
  azimuth: number;
  elevation: number;
  magnitude: number | null;
  daylight: boolean;
}

interface SkyObject {
  id: string;
  name: string;
  points: SkyPoint[];
}

export default function Home() {
  const [objects, setObjects] = useState<SkyObject[]>([]);
  const [place, setPlace] = useState<{ area: string | null; city: string | null } | null>(null);
  const [location, setLocation] = useState<{ lat: number; lon: number; alt: number | null } | null>(null);
  const [hourIndex, setHourIndex] = useState(0);
  const [status, setStatus] = useState<'locating' | 'loading' | 'ready' | 'error'>('locating');
  const [error, setError] = useState('');

  useEffect(() => {
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        setStatus('loading');
        const { latitude, longitude, altitude } = pos.coords;
        const alt = (altitude ?? 0) / 1000; // el navegador da metros, Horizons quiere km
        fetch(`/api/place?lat=${latitude}&lon=${longitude}`)
          .then((r) => r.json())
          .then(setPlace)
          .catch(() => setPlace(null));

        setLocation({ lat: latitude, lon: longitude, alt: alt });
        try {
          const res = await fetch(`/api/sky?lat=${latitude}&lon=${longitude}&alt=${alt}`);
          if (!res.ok) throw new Error((await res.json()).error);
          setObjects(await res.json());
          setStatus('ready');
        } catch (e) {
          setError(e instanceof Error ? e.message : 'Error desconocido');
          setStatus('error');
        }
      },
      () => {
        setError('Necesitamos tu ubicación para saber qué cielo ves');
        setStatus('error');
      }
    );
  }, []);

  if (status === 'locating') return <p className="p-8">Buscando tu ubicación…</p>;
  if (status === 'loading') return <p className="p-8">Consultando a la NASA…</p>;
  if (status === 'error') return <p className="p-8 text-red-500">{error}</p>;

  function getStatus(point: SkyPoint): string {
    if (point.elevation < 0) {
      return 'Bajo el horizonte';
    }
    if (point.daylight) {
      return 'Es de día no se ve';
    }
    if (point.elevation < 10) {
      return `Muy bajo (${point.elevation.toFixed(0)}°), puede taparlo algún edificio`;
    }
    return `Visible: mira a ${point.azimuth.toFixed(0)}°, a ${point.elevation.toFixed(0)}° de altura`;
  }

  function formatCoords(lat: number, lon: number): string {
    const fmt = new Intl.NumberFormat('es-CO', { maximumFractionDigits: 2, minimumFractionDigits: 2 });
    const ns = lat >= 0 ? 'N' : 'S';
    const eo = lon >= 0 ? 'E' : 'O';
    return `${fmt.format(Math.abs(lat))}° ${ns} · ${fmt.format(Math.abs(lon))}° ${eo}`;
  }

  function nightLabel(now: Date = new Date()): string {
    // Antes de las 6 a. m., "esta noche" empezó ayer
    const start = new Date(now);
    if (now.getHours() < 6) start.setDate(start.getDate() - 1);

    const end = new Date(start);
    end.setDate(end.getDate() + 1);

    const weekday = (d: Date) => new Intl.DateTimeFormat('es-CO', { weekday: 'long' }).format(d);
    const month = (d: Date) => new Intl.DateTimeFormat('es-CO', { month: 'long' }).format(d);
    const capitalize = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

    const from = `${capitalize(weekday(start))} ${start.getDate()}`;
    const to = `${weekday(end)} ${end.getDate()} de ${month(end)}`;

    return start.getMonth() === end.getMonth()
      ? `${from} al ${to}`
      : `${from} de ${month(start)} al ${to}`;
  }

  const placeName = place?.area ?? place?.city ?? 'tu ubicación';
  const time = objects[0]?.points[hourIndex]?.timeUTC;
  const max = Math.max((objects[0]?.points.length ?? 1) - 1, 0);
  const progress = max > 0 ? (hourIndex / max) * 100 : 0;


  return (
    <main className="p-8 bg-[#0A0F1D]">
      <div className="flex justify-between items-start mb-6">
        <span className="text-[12px] text-[#deb453] font-medium tracking-[0.2em]">UPTONIGHT</span>
        <span className="text-[12px] text-[#A8A293]">
          {location ? formatCoords(location.lat, location.lon) : ''}
        </span>
      </div>
      <h1>El cielo de esta noche sobre {placeName}</h1>
      <p className="text-sm text-[#A8A293]">
        {nightLabel()}
      </p>

      <div>
        <div>
          Noche cerrada: {new Date().toLocaleDateString('es-CO', { dateStyle: 'long' })}

          <p>
            {time && new Intl.DateTimeFormat('es-CO', { hour: 'numeric', minute: '2-digit' }).format(new Date(time))}
          </p>
        </div>
        <input
          type="range"
          className="sky-range"
          min={0}
          max={max}
          value={hourIndex}
          onChange={(e) => setHourIndex(Number(e.target.value))}
          style={{ '--progress': `${progress}%` } as React.CSSProperties}
        />
      </div>
      <ul className="space-y-3">
        {objects.map((obj) => (
          <li key={obj.id} className="border rounded-lg p-4">
            <p className="font-medium">{obj.name}</p>
            <p className="text-sm text-gray-500">{getStatus(obj.points[hourIndex])}</p>
          </li>
        ))}
      </ul>
    </main>
  );
}